def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    th = sep_rows[0] if sep_rows else h
    tw = sep_cols[0] if sep_cols else w
    rs = th + 1 if sep_rows else th
    cs = tw + 1 if sep_cols else tw
    tiles = []
    for r in range(0, h, rs):
        for c in range(0, w, cs):
            if r + th <= h and c + tw <= w:
                tiles.append([[grid[rr][cc] for cc in range(c, c + tw)]
                              for rr in range(r, r + th)])
    out = [[0] * tw for _ in range(th)]
    for i in range(th):
        for j in range(tw):
            counts = {}
            for tile in tiles:
                counts[tile[i][j]] = counts.get(tile[i][j], 0) + 1
            base = max(counts, key=counts.get)
            out[i][j] = 1 if any(t[i][j] != base for t in tiles) else base
    return out
